{"code":"import csv, os
infile='input/measurements.csv'
outfile='output/normalized.csv'
rows=[]
with open(infile, newline='', encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for row in reader:
        id_=row['id']
        s=row['value'].strip().strip('"')
        # parse per skill/source metadata
        if s.lower()=='nan' or s=='':
            v=None
        else:
            if 'e' in s.lower():
                try:
                    v=float(s)
                except ValueError:
                    v=None
            else:
                s=s.replace(',','.')
                try:
                    v=float(s)
                except ValueError:
                    v=None
        rows.append((id_, v))
with open(outfile, 'w', newline='', encoding='utf-8') as f:
    w=csv.writer(f)
    w.writerow(['id','value'])
    for id_, v in rows:
        w.writerow([id_, '' if v is None else f'{v:.3f}'])
print('wrote', outfile, 'rows', len(rows))
"}
